-- Vantage — committed static seed (GENERATED by scripts/generate_seed.py).
-- Do not edit by hand: change the generator and re-run, then commit this file.
--
-- Hybrid provenance (ADR-005): Faker (seeded) owns structure; Claude authored the
-- issue text + multi-update histories. Deterministic + offline (no runtime LLM).
-- Loaded by Postgres AFTER db/schema.sql. Dates are relative to load time.
--
-- Volume: 3 users (one per role) · 12 customers · 40 issues (26 open) · 132 updates · 14 next actions.
--
-- Planted eval scenarios:
--   E1  not-found  : query an ABSENT name, e.g. 'Zzzz Holdings Ltd' or 'Globex Foobar Inc' — no such customer exists.
--   E2  ambiguous  : 'Lumen Commerce' (id 2) vs 'Lumen Commerce Group' (id 3) — same name root, different account_ref + region.
--   E3  no-open     : 'Calm Waters Subscriptions' (id 4) — exists, every issue resolved/closed.
--   HERO High/Crit : 'Velocity Marketplace' (id 1) — open KYC hold blocking go-live, repeated payout failures, critical webhook outage.

BEGIN;

-- users: Acme internal operators. role mirrors Keycloak (attribution only; ADR-002).

-- customers: Acme's customers. account_ref + region disambiguate the E2 twins.

-- issues: "open" = status IN ('open','in_progress','pending').

-- issue_updates: append-only history the agent summarises.

-- next_actions: admin-owned directives (created_by = admin; RBAC at the tool, ADR-002).

-- Advance identity sequences past the seeded ids (we set ids explicitly above).
SELECT setval(pg_get_serial_sequence('users', 'id'), (SELECT COALESCE(MAX(id), 1) FROM users));
SELECT setval(pg_get_serial_sequence('customers', 'id'), (SELECT COALESCE(MAX(id), 1) FROM customers));
SELECT setval(pg_get_serial_sequence('issues', 'id'), (SELECT COALESCE(MAX(id), 1) FROM issues));
SELECT setval(pg_get_serial_sequence('issue_updates', 'id'), (SELECT COALESCE(MAX(id), 1) FROM issue_updates));
SELECT setval(pg_get_serial_sequence('next_actions', 'id'), (SELECT COALESCE(MAX(id), 1) FROM next_actions));

COMMIT;
