INSERT INTO issues (id, customer_id, title, description, category, status, priority, assigned_to, created_at, updated_at) VALUES
  (1, 1, 'KYC review blocking marketplace go-live', 'Enhanced due-diligence on the marketplace entity is outstanding; go-live for connected-account payouts is blocked until compliance signs off. Incorporation docs are in, but UBO verification for two beneficial owners is still pending.', 'onboarding_compliance', 'in_progress', 'critical', 2, now() - interval '96 days 23 hours', now() - interval '9 days 12 hours'),
  (2, 1, 'Repeated payout failures to connected accounts', 'Three consecutive daily payout batches to connected accounts have partially failed, returning funds to the platform balance. Sellers are chasing missing settlements and the customer is escalating.', 'payments', 'in_progress', 'high', 2, now() - interval '34 days 23 hours', now() - interval '4 days 17 hours'),
  (3, 1, 'Webhook delivery failing — signature mismatch after key rotation', 'Since the customer rotated their API signing secret, all webhook deliveries are rejected at their endpoint with signature-verification errors. Order fulfilment is stalled because their system never receives payment_succeeded events.', 'integration', 'open', 'critical', 2, now() - interval '6 days 23 hours', now() - interval '3 days 15 hours'),
  (4, 1, 'Dashboard latency during the settlement window', 'The customer reports the reporting dashboard takes 20-40s to load between 23:00 and 00:00 UTC, overlapping the nightly settlement run.', 'performance', 'pending', 'medium', 2, now() - interval '15 days 23 hours', now() - interval '12 days 6 hours'),
  (5, 1, 'Disputed platform fee on the April invoice', 'Customer queried a platform fee line on the April invoice they believed had been waived under a promo.', 'billing', 'resolved', 'low', 2, now() - interval '72 days 23 hours', now() - interval '64 days 4 hours'),
  (6, 2, 'Invoice total higher than expected', 'Customer asks why the latest invoice is ~18% higher than last month; suspects an unexpected charge.', 'billing', 'open', 'medium', 2, now() - interval '11 days 23 hours', now() - interval '8 days 18 hours'),
  (7, 2, 'Intermittent webhook retries on refund events', 'A fraction of refund webhooks are delivered twice; customer wants to confirm idempotency handling.', 'integration', 'in_progress', 'medium', 2, now() - interval '20 days 23 hours', now() - interval '14 days 9 hours'),
  (8, 2, 'Help rotating a leaked restricted API key', 'Customer accidentally committed a restricted key to a public repo and needed it rotated.', 'access', 'resolved', 'low', 2, now() - interval '40 days 23 hours', now() - interval '39 days'),
  (9, 3, 'Payout delayed beyond the expected schedule', 'A scheduled payout has not arrived two business days past the expected date; customer needs settlement confirmation.', 'payments', 'open', 'high', 2, now() - interval '5 days 23 hours', now() - interval '2 days 14 hours'),
  (10, 3, 'Additional KYC documents requested for a new entity', 'Customer is adding a second trading entity and compliance has requested supporting documents.', 'onboarding_compliance', 'pending', 'medium', 2, now() - interval '18 days 23 hours', now() - interval '13 days 5 hours'),
  (11, 3, 'One-off slow API responses during a provider incident', 'Elevated API latency reported during a known upstream provider incident.', 'performance', 'closed', 'low', 2, now() - interval '80 days 23 hours', now() - interval '78 days 19 hours'),
  (12, 4, 'Proration question on a mid-cycle plan change', 'Customer wanted to understand how a mid-cycle upgrade would be prorated.', 'billing', 'resolved', 'low', 2, now() - interval '50 days 23 hours', now() - interval '48 days 10 hours'),
  (13, 4, 'SSO setup for the dashboard', 'Customer configured SAML SSO for their team''s dashboard access.', 'access', 'closed', 'medium', 2, now() - interval '90 days 23 hours', now() - interval '85 days 8 hours'),
  (14, 4, 'Sandbox webhook test not firing', 'Customer''s sandbox endpoint was not receiving test webhooks during integration.', 'integration', 'resolved', 'low', 2, now() - interval '120 days 23 hours', now() - interval '118 days 22 hours'),
  (15, 5, 'API returning HTTP 429 on the /v1/payouts endpoint', 'Calls to the /v1/payouts endpoint intermittently return HTTP 429; customer wants to know if it is on their side or ours.', 'integration', 'pending', 'medium', 3, now() - interval '135 days 23 hours', now() - interval '37 days 4 hours'),
  (16, 5, 'Failed payout batch PB-5240', 'Payout batch PB-5240 totalling GBP 48,000 to 6 connected accounts failed at the banking partner; funds returned to the balance.', 'payments', 'open', 'low', 3, now() - interval '59 days 23 hours', now() - interval '29 days 2 hours'),
  (17, 6, 'Webhook endpoint returning HTTP 401 errors', 'Customer''s endpoint is returning HTTP 401 for a portion of webhook deliveries, so some events are not being processed.', 'integration', 'open', 'medium', 2, now() - interval '38 days 23 hours', now() - interval '24 days'),
  (18, 6, 'Elevated API latency from the EU region', 'Customer reports elevated API latency for requests originating from the EU region.', 'performance', 'open', 'medium', 2, now() - interval '132 days 23 hours', now() - interval '8 days 21 hours'),
  (19, 6, 'KYC documents requested before activation', 'Compliance has requested KYC documents before the account can be fully activated for live processing.', 'onboarding_compliance', 'in_progress', 'medium', 2, now() - interval '69 days 23 hours', now() - interval '16 days 3 hours'),
  (20, 6, 'Failed payout batch PB-6383', 'Payout batch PB-6383 totalling GBP 14,800 to 34 connected accounts failed at the banking partner; funds returned to the balance.', 'payments', 'resolved', 'high', 2, now() - interval '56 days 23 hours', now() - interval '1 days 8 hours'),
  (21, 7, 'KYC documents requested before activation', 'Compliance has requested KYC documents before the account can be fully activated for live processing.', 'onboarding_compliance', 'pending', 'low', 3, now() - interval '127 days 23 hours', now() - interval '41 days 13 hours'),
  (22, 7, 'Request for a new restricted API key with scoped permissions', 'Customer needs a restricted API key scoped to read-only reporting for a new internal tool.', 'access', 'open', 'low', 2, now() - interval '24 days 23 hours', now() - interval '18 days 11 hours'),
  (23, 7, 'Query on the February invoice', 'Customer has a question about a line item on their February invoice and wants it explained before paying.', 'billing', 'pending', 'high', 2, now() - interval '116 days 23 hours', now() - interval '17 days 16 hours'),
  (24, 8, 'Webhook endpoint returning HTTP 429 errors', 'Customer''s endpoint is returning HTTP 429 for a portion of webhook deliveries, so some events are not being processed.', 'integration', 'in_progress', 'medium', 2, now() - interval '41 days 23 hours', now() - interval '26 days 21 hours'),
  (25, 8, 'Locked out of the dashboard after an SSO change', 'An admin user is locked out of the dashboard following a change to the customer''s SSO configuration.', 'access', 'closed', 'medium', 3, now() - interval '72 days 23 hours', now() - interval '22 days 3 hours'),
  (26, 8, 'Source-of-funds questionnaire outstanding', 'A source-of-funds questionnaire is outstanding on the account following a routine review.', 'onboarding_compliance', 'resolved', 'medium', 2, now() - interval '145 days 23 hours', now() - interval '71 days 8 hours'),
  (27, 8, 'Elevated API latency from the US-East region', 'Customer reports elevated API latency for requests originating from the US-East region.', 'performance', 'open', 'low', 3, now() - interval '76 days 23 hours', now() - interval '20 days 6 hours'),
  (28, 9, 'Slow report generation for large date ranges', 'Generating reports across large date ranges is slow for the customer during business hours.', 'performance', 'open', 'medium', 3, now() - interval '98 days 23 hours', now() - interval '16 days 4 hours'),
  (29, 9, 'Customer disputing a card payment for GBP 9,900', 'A cardholder has disputed a GBP 9,900 payment; the customer needs help compiling evidence for the chargeback.', 'payments', 'resolved', 'low', 3, now() - interval '88 days 23 hours', now() - interval '8 days 9 hours'),
