  (31, 10, 'Request to change billing cycle to January', 'Customer asked to move their billing anchor date and understand the proration impact.', 'billing', 'open', 'low', 3, now() - interval '37 days 23 hours', now() - interval '21 days 12 hours'),
  (32, 10, 'Failed payout batch PB-3897', 'Payout batch PB-3897 totalling GBP 5,000 to 24 connected accounts failed at the banking partner; funds returned to the balance.', 'payments', 'resolved', 'low', 2, now() - interval '44 days 23 hours', now() - interval '1 days 17 hours'),
  (33, 10, 'Locked out of the dashboard after an SSO change', 'An admin user is locked out of the dashboard following a change to the customer''s SSO configuration.', 'access', 'in_progress', 'medium', 2, now() - interval '16 days 23 hours', now() - interval '1 days 15 hours'),
