  (8, 2, 2, 'Status -> in_progress. Payments engineering reproducing against the partner sandbox; customer asked to re-verify payee details for the affected sellers.', 'status_change', now() - interval '16 days 10 hours'),
  (9, 2, 3, 'Still recurring on the latest batch. Keeping high priority until two clean payout cycles are observed.', 'note', now() - interval '4 days 17 hours'),
  (10, 3, 2, 'Reproduced: deliveries return HTTP 401 ''invalid signature'' from the customer endpoint. They appear to still verify against the old secret.', 'note', now() - interval '6 days 1 hours'),
